
CREATE TABLE sellers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_name TEXT NOT NULL, corporate_affairs_commission_number TEXT UNIQUE NOT NULL, phone_number TEXT, state TEXT, local_government_area TEXT, verification_status TEXT DEFAULT 'pending', verified_badge BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_material_name TEXT NOT NULL, category TEXT, unit_of_measurement TEXT, anti_fake_qr_code TEXT, seller_id uuid REFERENCES sellers(id), verified_authentic BOOLEAN DEFAULT false);
CREATE TABLE city_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid REFERENCES products(id), full_material_name TEXT NOT NULL, city TEXT NOT NULL, state TEXT, price_in_naira INTEGER, trend_percentage DECIMAL, source_market_name TEXT, last_updated TIMESTAMPTZ DEFAULT now());
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_phone TEXT, full_material_name TEXT, quantity INTEGER, total_amount_naira INTEGER, escrow_status TEXT DEFAULT 'funds_held', delivery_address TEXT, delivery_photo_url TEXT, delivery_confirmed BOOLEAN DEFAULT false);
CREATE TABLE price_lock_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_phone TEXT, full_material_name TEXT, quantity INTEGER, locked_price_in_naira INTEGER, lock_fee_in_naira INTEGER DEFAULT 2500, deposit_percentage INTEGER DEFAULT 30, expiry_date TIMESTAMPTZ, paystack_reference TEXT, status TEXT DEFAULT 'active');
